from PIL import Image
im = Image.open('r152-gutter-light.png').convert('RGB')
px = im.load()
rows = {}
for y in range(236, im.size[1]):
    xs = [x for x in range(221, 271) if sum(px[x,y])/3 < 180]
    if xs:
        rows[y] = (min(xs), max(xs), len(xs))
labels = []
cur = []; prev = None
for y in sorted(rows):
    if prev is not None and y - prev > 3:
        labels.append(cur); cur = []
    cur.append(y); prev = y
if cur: labels.append(cur)
print('count', len(labels))
for L in labels:
    y0,y1 = L[0],L[-1]
    x0 = min(rows[y][0] for y in L); x1 = max(rows[y][1] for y in L)
    print(f'y{y0}..{y1} h={y1-y0+1} x{x0}..{x1}')
EOF

